def build_agent(sandbox):
    # Wiper base (fixed to glass)
    base = sandbox.add_beam(x=6.0, y=2.06, width=0.5, height=0.12, angle=0, density=1.0)
    if hasattr(sandbox, 'weld_to_glass'):
        sandbox.weld_to_glass(base, (6.0, 2.0))

    # Create wiper as a single long beam spanning the glass width
    wiper = sandbox.add_beam(x=6.0, y=2.1, width=0.5, height=0.12, angle=0, density=1.0)
    sandbox.set_material_properties(wiper, restitution=0.0, friction=0.6)  # Optimal friction for particle pushing

    # Add pivot joint at the center of the wiper
    pivot_joint = sandbox.add_joint(
        base, wiper, (6.0, 2.1), type='pivot',
        lower_limit=-math.pi, upper_limit=math.pi  # Full rotation
    )

    return {"body": wiper, "motors": [pivot_joint]}

